const input = $input.first()?.json ?? {};

const p = {
  ...input,
  ...(input.body && typeof input.body === 'object' ? input.body : {}),
  ...(input.data && typeof input.data === 'object' ? input.data : {}),
  ...(input.payload && typeof input.payload === 'object' ? input.payload : {})
};

const action = String(
  p.action || p.operation || p.event || ''
).trim();

const uuid = (v) => typeof v === 'string' &&
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v);

const enc = (v) => encodeURIComponent(String(v));

const fail = (message) => {
  throw new Error(message);
};

if (!action) {
  fail(
    'Missing action. Send action in the input JSON. ' +
    'Supported actions: student.create, student.update, student.get, ' +
    'student.search, student.enroll, student.enrollment.update, ' +
    'student.enrollments.list, student.enrollment.remove. ' +
    'Received fields: ' + Object.keys(input).join(', ')
  );
}

const base = 'https://zhbntxnsdznpdqmjyxpp.supabase.co/rest/v1';
let method = 'GET';
let path = '';
let body = undefined;
let prefer = 'return=representation';

switch (action) {
  case 'student.create':
  case 'user.create':
  case 'teacher.create':
  case 'parent.create': {
    const role = p.role || (action.startsWith('teacher') ? 'teacher' : (action.startsWith('parent') ? 'parent' : 'student'));
    const cleanId = uuid(p.student_id) ? p.student_id : (uuid(p.id) ? p.id : '00000000-0000-4000-8000-' + String(Date.now()).padStart(12, '0').slice(-12));
    if (!p.full_name || !String(p.full_name).trim()) fail('full_name is required.');
    if (!p.email || !String(p.email).trim()) fail('email is required.');
    body = { id: cleanId, full_name: String(p.full_name).trim(), email: String(p.email).trim().toLowerCase(), role };
    if (p.phone !== undefined) body.phone = p.phone === null ? null : String(p.phone).trim();
    method = 'POST'; path = '/profiles?on_conflict=id'; prefer = 'resolution=merge-duplicates,return=representation';
    break;
  }
  case 'student.update': {
    if (!uuid(p.student_id)) fail('student_id must be a valid UUID.');
    body = {};
    for (const key of ['full_name','email','phone']) if (Object.prototype.hasOwnProperty.call(p,key)) body[key] = key === 'email' && p[key] ? String(p[key]).trim().toLowerCase() : p[key];
    if (!Object.keys(body).length) fail('Provide at least one of full_name, email, or phone.');
    if (body.full_name !== undefined && !String(body.full_name).trim()) fail('full_name cannot be empty.');
    if (body.email !== undefined && !String(body.email).trim()) fail('email cannot be empty.');
    method = 'PATCH'; path = `/profiles?id=eq.${enc(p.student_id)}&role=eq.student`;
    break;
  }
  case 'student.get': {
    if (!uuid(p.student_id)) fail('student_id must be a valid UUID.');
    path = `/profiles?id=eq.${enc(p.student_id)}&role=eq.student&select=id,full_name,email,phone,role,created_at`;
    break;
  }
  case 'student.search': {
    const term = String(p.search || '').trim();
    if (term.length < 2) fail('search must contain at least 2 characters.');
    path = `/profiles?role=eq.student&select=id,full_name,email,phone,created_at&or=(full_name.ilike.*${enc(term)}*,email.ilike.*${enc(term)}*,phone.ilike.*${enc(term)}*)&order=full_name.asc&limit=${Math.min(Math.max(Number(p.limit)||25,1),100)}`;
    break;
  }
  case 'student.enroll': {
    if (!uuid(p.student_id) || !uuid(p.group_id)) fail('student_id and group_id must be valid UUIDs.');
    body = { student_id: p.student_id, group_id: p.group_id, status: 'active' };
    method = 'POST'; path = '/enrollments?on_conflict=student_id,group_id';
    prefer = 'resolution=merge-duplicates,return=representation';
    break;
  }
  case 'student.enrollment.update': {
    if (!uuid(p.enrollment_id)) fail('enrollment_id must be a valid UUID.');
    if (!['active','completed','cancelled'].includes(p.status)) fail('status must be active, completed, or cancelled.');
    body = { status: p.status };
    method = 'PATCH'; path = `/enrollments?id=eq.${enc(p.enrollment_id)}`;
    break;
  }
  case 'student.enrollments.list': {
    if (!uuid(p.student_id)) fail('student_id must be a valid UUID.');
    path = `/enrollments?student_id=eq.${enc(p.student_id)}&select=id,student_id,group_id,enrolled_at,status,course_groups(id,name,workspace_id,course_id)&order=enrolled_at.desc`;
    break;
  }
  case 'student.enrollment.remove': {
    if (!uuid(p.enrollment_id)) fail('enrollment_id must be a valid UUID.');
    // Soft removal: preserve historical records by marking the enrollment cancelled.
    body = { status: 'cancelled' };
    method = 'PATCH'; path = `/enrollments?id=eq.${enc(p.enrollment_id)}`;
    break;
  }
  default: fail(`Unsupported action: ${action || '(missing)'}`);
}

return [{ json: {
  action,
  http_method: method,
  request_url: base + path,
  request_body: body,
  request_body_str: body !== undefined ? JSON.stringify(body) : null,
  prefer,
  student_id: p.student_id || null,
  _note: 'This workflow expects a trusted server-side caller. Do not expose the Supabase secret or call this workflow directly from an untrusted browser.'
} }];
